import 'package:flutter/material.dart';import '../../../core/theme/app_theme.dart';import '../../../core/widgets/brand_mark.dart';
class StepHeader extends StatelessWidget{final int step;const StepHeader({super.key,required this.step});Widget build(BuildContext c)=>Column(children:[Row(children:[IconButton(onPressed:()=>Navigator.maybePop(c),icon:const Icon(Icons.chevron_left)),Expanded(child:LinearProgressIndicator(value:(step+1)/3,minHeight:5,borderRadius:BorderRadius.circular(8),color:AppColors.primary,backgroundColor:AppColors.border))]),Text('Шаг '+(step+1).toString()+' из 3',style:const TextStyle(fontSize:10,color:AppColors.muted,fontWeight:FontWeight.w700)),const SizedBox(height:12)]);}
class OnboardingFrame extends StatelessWidget{final Widget child;const OnboardingFrame({super.key,required this.child});Widget build(BuildContext c)=>Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:520),child:Padding(padding:const EdgeInsets.fromLTRB(20,10,20,20),child:child)));}
class SecondaryButton extends StatelessWidget{final String label;final VoidCallback onPressed;const SecondaryButton({super.key,required this.label,required this.onPressed});Widget build(BuildContext c)=>SizedBox(width:double.infinity,height:44,child:OutlinedButton(onPressed:onPressed,style:OutlinedButton.styleFrom(shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(12))),child:Text(label)));}
class LogoRow extends StatelessWidget{const LogoRow({super.key});Widget build(BuildContext c)=>const Row(mainAxisAlignment:MainAxisAlignment.center,children:[BrandMark(size:27),SizedBox(width:7),Text('HabitPulse',style:TextStyle(fontSize:20,fontWeight:FontWeight.w800,color:AppColors.text))]);}
